 namespace Slim; if (!extension_loaded('mcrypt')) { define('MCRYPT_MODE_CBC', 0); define('MCRYPT_RIJNDAEL_256', 0); } class Slim { const VERSION = '2.6.1'; public $container; protected static $apps = array(); protected $name; protected $middleware; protected $error; protected $notFound; protected $hooks = array( 'slim.before' => array(array()), 'slim.before.router' => array(array()), 'slim.before.dispatch' => array(array()), 'slim.after.dispatch' => array(array()), 'slim.after.router' => array(array()), 'slim.after' => array(array()) ); public static function autoload($className) { $thisClass = str_replace(__NAMESPACE__.'\\', '', __CLASS__); $baseDir = __DIR__; if (substr($baseDir, -safe_strlen($thisClass)) === $thisClass) { $baseDir = substr($baseDir, 0, -safe_strlen($thisClass)); } $className = ltrim($className, '\\'); $fileName = $baseDir; $namespace = ''; if ($lastNsPos = strripos($className, '\\')) { $namespace = substr($className, 0, $lastNsPos); $className = substr($className, $lastNsPos + 1); $fileName .= str_replace('\\', DIRECTORY_SEPARATOR, $namespace) . DIRECTORY_SEPARATOR; } $fileName .= str_replace('_', DIRECTORY_SEPARATOR, $className) . '.php'; if (file_exists($fileName)) { require $fileName; } } public static function registerAutoloader() { spl_autoload_register(__NAMESPACE__ . "\\Slim::autoload"); } public function __construct(array $userSettings = array()) { $this->container = new \Slim\Helper\Set(); $this->container['settings'] = array_merge(static::getDefaultSettings(), $userSettings); $this->container->singleton('environment', function ($c) { return \Slim\Environment::getInstance(); }); $this->container->singleton('request', function ($c) { return new \Slim\Http\Request($c['environment']); }); $this->container->singleton('response', function ($c) { return new \Slim\Http\Response(); }); $this->container->singleton('router', function ($c) { return new \Slim\Router(); }); $this->container->singleton('view', function ($c) { $viewClass = $c['settings