value === false ? null : $value; } public function setEncryptedCookie($name, $value, $expires = null, $path = null, $domain = null, $secure = false, $httponly = false) { $this->setCookie($name, $value, $expires, $path, $domain, $secure, $httponly); } public function getEncryptedCookie($name, $deleteIfInvalid = true) { return $this->getCookie($name, $deleteIfInvalid); } public function deleteCookie($name, $path = null, $domain = null, $secure = null, $httponly = null) { $settings = array( 'domain' => is_null($domain) ? $this->config('cookies.domain') : $domain, 'path' => is_null($path) ? $this->config('cookies.path') : $path, 'secure' => is_null($secure) ? $this->config('cookies.secure') : $secure, 'httponly' => is_null($httponly) ? $this->config('cookies.httponly') : $httponly ); $this->response->cookies->remove($name, $settings); } public function root() { return rtrim($_SERVER['DOCUMENT_ROOT'], '/') . rtrim($this->request->getRootUri(), '/') . '/'; } protected function cleanBuffer() { if (ob_get_level() !== 0) { ob_clean(); } } public function stop() { throw new \Slim\Exception\Stop(); } public function halt($status, $message = '') { $this->cleanBuffer(); $this->response->status($status); $this->response->body($message); $this->stop(); } public function pass() { $this->cleanBuffer(); throw new \Slim\Exception\Pass(); } public function contentType($type) { $this->response->headers->set('Content-Type', $type); } public function status($code) { $this->response->setStatus($code); } public function urlFor($name, $params = array()) { return $this->request->getRootUri() . $this->router->urlFor($name, $params); } public function redirect($url, $status = 302) { $this->response->redirect($url, $status); $this->halt($status); } public function redirectTo($route, $params = array(), $status = 302){ $this->redirect($this->urlFor($route, $params), $status); } public function flash($key, $value) { if (isset($this->environment['slim.flash'])) { $this->environment['slim.flash']->se